// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(
            42,
            100,
            200,
            bytes32(uint256(1)),
            300,
            bytes32(uint256(2)),
            400,
            500
        );
        uint64 expectedNumber = 42;
        assertTrue(c.number() == expectedNumber, "number should be 42 in reference");
    }
}
